/* Offline guide. All calculations are generated by the repository Python code. */
(() => {
  'use strict';
  const data = window.ALGORITHM_GUIDE;
  const $ = id => document.getElementById(id);
  if (!data?.lessons?.length) {
    $('title').textContent = 'The example data is missing.';
    $('intro').textContent = 'Keep examples.js beside this HTML file, or rebuild it with scripts/build_algorithm_guide.py.';
    return;
  }
  const lessons = data.lessons;
  const charts = [];
  let activeLesson, activeVariant, activeTab = 'code', toastTimer;
  const number = value => {
    if (value == null) return 'Not provided';
    if (typeof value === 'boolean') return value ? 'Yes' : 'No';
    if (typeof value === 'number') {
      if (value !== 0 && Math.abs(value) < .001) return value.toExponential(2);
      return new Intl.NumberFormat('en', { maximumFractionDigits: 4 }).format(value);
    }
    return String(value);
  };
  const make = (tag, cls, text) => {
    const el = document.createElement(tag);
    if (cls) el.className = cls;
    if (text != null) el.textContent = text;
    return el;
  };
  const toast = message => {
    clearTimeout(toastTimer);
    $('toast').textContent = message;
    $('toast').hidden = false;
    toastTimer = setTimeout(() => { $('toast').hidden = true; }, 4500);
  };
  const groupLabels = {0: 'Describe the data', 5: 'Investigate a change', 8: 'Explore a decision'};
  lessons.forEach((item, i) => {
    if (groupLabels[i]) $('topics').append(make('p', 'nav-group', groupLabels[i]));
    const a = make('a', 'nav-link');
    a.href = `#${item.key}/${item.variants[0].key}`;
    a.dataset.topic = item.key;
    a.append(make('span', 'nav-number', String(i + 1).padStart(2, '0')), make('span', '', item.short));
    $('topics').append(a);
  });

  function table(columns, rows) {
    const t = make('table');
    t.append(make('caption', 'sr-only', `${activeLesson.short}: ${activeVariant.label}. Calculated example values.`));
    const head = make('thead'), hrow = make('tr');
    columns.forEach(name => { const th = make('th', '', name); th.scope = 'col'; hrow.append(th); });
    head.append(hrow); t.append(head);
    const body = make('tbody');
    rows.forEach(row => {
      const tr = make('tr');
      row.forEach(value => tr.append(make('td', '', number(value))));
      body.append(tr);
    });
    t.append(body);
    return t;
  }

  function chartOption(raw, narrow, topic) {
    const option = structuredClone(raw);
    option.animation = false;
    option.aria = {enabled: true};
    option.color = ['#3569b7', '#087f75', '#95a3b5', '#a44157'];
    option.textStyle = {fontFamily: 'system-ui, sans-serif', fontSize: 11, color: '#354844'};
    option.tooltip = {...option.tooltip, renderMode: 'richText', confine: true};
    if (option.legend && narrow) {
      option.legend = {...option.legend, left: 0, top: 0, itemWidth: 13, itemHeight: 8, itemGap: 10, textStyle: {fontSize: 10}};
    }
    if (!Array.isArray(option.grid)) {
      option.grid = {left: 14, right: 32, bottom: 40, top: 38, containLabel: true, ...option.grid};
      if (narrow && option.legend) option.grid.top = 70;
      if (topic === 'correlation' && option.series[0]?.type === 'heatmap') {
        option.grid = {top: 14, left: narrow ? 85 : 120, right: 25, bottom: narrow ? 115 : 110};
        option.xAxis.axisLabel = {rotate: 40, fontSize: 10, width: 90, overflow: 'truncate'};
        option.yAxis.axisLabel = {fontSize: 10, width: narrow ? 76 : 110, overflow: 'truncate'};
        option.series[0].label = {show: true, fontSize: narrow ? 10 : 11, formatter: p => p.value[2].toFixed(2)};
        option.visualMap.text = ['+1', '−1'];
        option.visualMap.textStyle = {fontSize: 10};
      }
    } else {
      // The timeline keeps a shared X scale but each metric owns its Y axis.
      option.grid.forEach(g => {g.left = narrow ? 48 : 55; g.right = narrow ? 18 : 30;});
      option.yAxis.forEach(a => {
        a.nameLocation = 'end';
        a.nameTextStyle = {...a.nameTextStyle, align: 'left', fontSize: 10};
        a.axisLabel = {...a.axisLabel, fontSize: 10};
      });
    }
    const axes = a => a ? (Array.isArray(a) ? a : [a]) : [];
    axes(option.xAxis).forEach(a => {
      a.axisLabel = {fontSize: 10, hideOverlap: true, showMaxLabel: true, ...a.axisLabel};
      if (a.type === 'category' && a.data?.length > 15) a.axisLabel.interval = narrow ? 6 : Math.max(1, Math.floor(a.data.length / 6));
      a.nameTextStyle = {fontSize: 10, ...a.nameTextStyle};
      if (a.name) { a.nameLocation = 'middle'; a.nameGap = 30; }
    });
    axes(option.yAxis).forEach(a => {
      a.nameTextStyle = {fontSize: 10, align: 'left', ...a.nameTextStyle};
      if (a.type === 'category' && a.name) { a.nameLocation = 'middle'; a.nameGap = 45; }
    });
    if (topic === 'spotlight') {
      option.yAxis.axisLabel = {...option.yAxis.axisLabel, width: narrow ? 90 : 160, overflow: 'break', fontSize: 10};
      option.grid.left = 4;
      option.grid.right = narrow ? 40 : 65;
    }
    if (topic === 'bridge') {
      option.xAxis.axisLabel = {fontSize: 10, interval: 0, width: narrow ? 50 : 85, overflow: 'break', rotate: 0};
      option.grid.right = 48;
    }
    if (topic === 'recipes') {
      if (option.xAxis?.type === 'category') {
        option.xAxis.axisLabel = {fontSize: 10, interval: 0, width: narrow ? 65 : 110, overflow: 'break'};
      } else {
        option.xAxis.scale = true;
        option.yAxis.axisLabel = {fontSize: 10, width: 62, overflow: 'break'};
      }
    }
    (option.series || []).forEach(s => {
      if (s.type === 'bar' && !s.stack) s.label = {show: true, position: option.yAxis?.type === 'category' ? 'right' : 'top', fontSize: 11, color: '#354844'};
      if (s.type === 'line') {
        if (!s.lineStyle?.opacity && !s.areaStyle) s.lineStyle = {width: 2, ...s.lineStyle};
        s.emphasis = {disabled: true};
        if (s.markPoint) {
          s.markPoint.label = {...s.markPoint.label, fontSize: 10};
          (s.markPoint.data || []).forEach(item => {item.label = {...item.label, fontSize: 10};});
        }
      }
      if (s.type === 'pie') {
        s.radius = ['0%', '66%'];
        s.label = {fontSize: 12, formatter: '{b}\n{c} CU · {d}%'};
      }
    });
    return option;
  }

  function drawCharts() {
    for (const c of charts) c.dispose();
    charts.length = 0;
    $('chart-list').replaceChildren();
    $('chart-error').hidden = Boolean(window.echarts);
    const narrow = window.innerWidth < 600;
    activeVariant.charts.forEach((c, i) => {
      const panel = make('section', 'chart-panel');
      if (activeLesson.key === 'timeline') panel.classList.add('timeline');
      if (c.option.series?.[0]?.type === 'heatmap') panel.classList.add('heatmap');
      const heading = make('h2', '', c.title); heading.id = `chart-heading-${i}`;
      panel.setAttribute('aria-labelledby', heading.id);
      const el = make('div', 'chart'); el.id = `chart-${i}`;
      el.setAttribute('role', 'img');
      el.setAttribute('aria-label', `${c.title}. ${activeVariant.takeaway} ${c.note} See Check the numbers for exact values.`);
      const note = make('p', '', c.note);
      panel.append(heading, el, note); $('chart-list').append(panel);
      if (window.echarts) {
        try {
          const instance = window.echarts.init(el, null, {renderer: 'svg'});
          instance.setOption(chartOption(c.option, narrow, activeLesson.key), true);
          charts.push(instance);
        } catch (err) {
          el.replaceChildren(make('p', 'notice', 'This chart could not render. Use the checked values below.'));
          console.error(err);
        }
      } else el.append(make('p', 'notice', 'Chart unavailable. Read the values in the table below.'));
    });
  }

  function setTab(tab, focus = false) {
    activeTab = tab;
    document.querySelectorAll('[data-tab]').forEach(el => {
      const selected = el.dataset.tab === tab;
      el.setAttribute('aria-selected', String(selected)); el.tabIndex = selected ? 0 : -1;
      if (selected && focus) el.focus();
    });
    $('code-panel').setAttribute('aria-labelledby', `tab-${tab}`);
    const content = tab === 'code' ? activeLesson.code : tab === 'output' ? activeVariant.output : activeVariant.binding;
    $('code').textContent = typeof content === 'string' ? content : JSON.stringify(content, null, 2);
  }

  function render() {
    const previousTopic = activeLesson?.key;
    const parts = location.hash.slice(1).split('/');
    activeLesson = lessons.find(l => l.key === parts[0]) || lessons[0];
    activeVariant = activeLesson.variants.find(v => v.key === parts[1]) || activeLesson.variants[0];
    const canonical = `#${activeLesson.key}/${activeVariant.key}`;
    if (location.hash !== canonical) history.replaceState(null, '', canonical);
    const index = lessons.indexOf(activeLesson);
    document.title = `${activeLesson.short} · WPS-AI algorithm guide`;
    $('chapter').textContent = `Topic ${String(index + 1).padStart(2, '0')} / ${lessons.length}`;
    $('status').textContent = activeLesson.status;
    for (const name of ['title', 'question', 'intro', 'formula']) $(name).textContent = activeLesson[name];
    for (const name of ['takeaway', 'worked']) $(name).textContent = activeVariant[name];
    $('data-source').textContent = `Data: ${activeLesson.data}`;
    document.querySelectorAll('[data-topic]').forEach(el => {
      if (el.dataset.topic === activeLesson.key) el.setAttribute('aria-current', 'page');
      else el.removeAttribute('aria-current');
    });
    $('variant').replaceChildren(...activeLesson.variants.map(v => {
      const opt = make('option', '', v.label); opt.value = v.key; return opt;
    }));
    $('variant').value = activeVariant.key;
    $('metrics').replaceChildren(...activeVariant.metrics.map(([label, value]) => {
      const el = make('div', 'metric'); el.append(make('span', 'metric-label', label), make('strong', 'metric-value', value)); return el;
    }));
    $('steps').replaceChildren(...activeLesson.steps.map(([title, text]) => {
      const el = make('li'); el.append(make('h3', '', title), make('p', '', text)); return el;
    }));
    $('route').replaceChildren(...activeLesson.route.map(text => make('li', '', text)));
    $('limits').replaceChildren(...activeLesson.limits.map(text => make('li', '', text)));
    $('values-table').replaceChildren(table(activeVariant.columns, activeVariant.rows));
    (activeVariant.extra_tables || []).forEach(t => {
      $('values-table').append(make('h3', '', t.title), table(t.columns, t.rows));
    });
    $('sources').replaceChildren(...activeLesson.sources.map(path => {
      const a = make('a', '', path); a.href = `../../${path}`; return a;
    }));
    setTab(activeTab);
    drawCharts();
    const previous = lessons[index - 1], next = lessons[index + 1];
    $('previous').hidden = !previous;
    $('next').hidden = !next;
    if (previous) $('previous').href = `#${previous.key}/${previous.variants[0].key}`;
    if (next) $('next').href = `#${next.key}/${next.variants[0].key}`;
    $('result').textContent = `${activeLesson.short}. ${activeVariant.label}. ${activeVariant.metrics.map(m => m.join(': ')).join('. ')}. ${activeVariant.takeaway}`;
    if (previousTopic && previousTopic !== activeLesson.key) window.scrollTo(0, 0);
    window.GUIDE_READY = canonical;
  }

  $('variant').addEventListener('change', e => { location.hash = `${activeLesson.key}/${e.target.value}`; });
  $('reset').addEventListener('click', () => {
    activeTab = 'code';
    const hash = `#${activeLesson.key}/${activeLesson.variants[0].key}`;
    if (location.hash === hash) render(); else location.hash = hash;
  });
  document.querySelectorAll('[data-tab]').forEach(el => {
    el.addEventListener('click', () => setTab(el.dataset.tab));
    el.addEventListener('keydown', e => {
      const tabs = ['code', 'output', 'binding'];
      if (['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(e.key)) {
        e.preventDefault();
        const next = e.key === 'Home' ? 0 : e.key === 'End' ? 2 : (tabs.indexOf(activeTab) + (e.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length;
        setTab(tabs[next], true);
      }
    });
  });
  $('copy-link').addEventListener('click', async () => {
    try { await navigator.clipboard.writeText(location.href); toast('Example link copied.'); }
    catch {
      const input = make('textarea'); input.value = location.href;
      document.body.append(input); input.select();
      const copied = document.execCommand('copy'); input.remove();
      if (copied) toast('Example link copied.');
      else { toast('Copy the selected link from your browser address bar.'); }
    }
  });
  $('print').addEventListener('click', () => window.print());
  let wasOpen;
  addEventListener('beforeprint', () => { wasOpen = $('values-detail').open; $('values-detail').open = true; charts.forEach(c => c.resize()); });
  addEventListener('afterprint', () => { $('values-detail').open = wasOpen; charts.forEach(c => c.resize()); });
  let resizeTimer;
  addEventListener('resize', () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(drawCharts, 120); });
  addEventListener('hashchange', render);
  render();
})();
